/** Exercise the current production export and commit boundaries with fabricated
 * closed history. This is an artifact-density probe and makes no model calls. */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const repo = path.resolve(process.argv[2]);
const { exportLedger } = await import(pathToFileURL(path.join(repo, "governance", "ledger.mjs")));
const { commitWorkspaceState, STATE_LIMIT } = await import(pathToFileURL(path.join(repo, "governance", "transactions.mjs")));
const root = fs.mkdtempSync(path.join(path.dirname(fileURLToPath(import.meta.url)), "capacity-"));
const actor = "capacity-fixture-owner";

function sample(count, reasonChars) {
  const items = Object.fromEntries(Array.from({ length: count }, (_, i) => {
    const id = "item-" + String(i).padStart(6, "0");
    return [id, { id, owner: actor, kind: "planned", status: "obsolete", title: "容量测试条目 " + i,
      disposition: { outcome: "obsolete", checkpoint: "K01", basis: "证".repeat(reasonChars),
        evidence: { file: "OWNER.md", start: 1, end: 1, sha256: "a".repeat(64) } },
      updatedAt: "2026-11-01T00:00:00.000Z" }];
  }));
  const frame = { role: "coordinator", agent: { id: actor }, root,
    policy: { ledgerDocument: "LEDGER.md", coordinator: { write: ["LEDGER.md"] } },
    state: { ledger: { revision: count, items }, units: {}, markers: {} } };
  const bytes = Buffer.byteLength(JSON.stringify(frame.state));
  const start = performance.now();
  try {
    exportLedger(frame);
    const projection = frame.ledgerWrites.find(row => row.file === "LEDGER.md");
    return { count, reasonChars, bytes, status: "staged", projectedMarkdownBytes: projection.after.length,
      milliseconds: +(performance.now() - start).toFixed(2) };
  } catch (error) {
    return { count, reasonChars, bytes, status: "rejected", message: error.message,
      milliseconds: +(performance.now() - start).toFixed(2) };
  }
}

const commits = [STATE_LIMIT - 1, STATE_LIMIT, STATE_LIMIT + 1].map((length, n) => {
  // Valid JSON makes the measured serialized byte limit independent of filesystem layout.
  const next = Buffer.from('{"payload":"' + "x".repeat(length - 14) + '"}');
  if (next.length !== length) throw new Error("incorrect state fixture length");
  const file = "state-" + n + ".json";
  try {
    commitWorkspaceState(root, { root, file, old: null, policy: {} }, next);
    return { length, status: "written", written: fs.statSync(path.join(root, file)).size };
  } catch (error) {
    return { length, status: "rejected", message: error.message, exists: fs.existsSync(path.join(root, file)) };
  }
});
const exports = [60, 180, 500].flatMap(reasonChars => [50, 100, 250, 500, 1000, 2500].map(count => sample(count, reasonChars)));
const answer = { method: "actual production ledger export/transaction with synthetic completed records; no model or token throughput claim",
  fixedHistoryReasonLengths: [60, 180, 500], commits, exports };
fs.writeFileSync(path.join(root, "result.json"), JSON.stringify(answer, null, 2) + "\n");
console.log(JSON.stringify(answer, null, 2));
